function validate([a, b]) {
  if (!Array.isArray(a) || !Array.isArray(b)) return 'a and b must be lists of words.';
  if (a.length < 1 || b.length < 1 || a.length > 100000 || b.length > 100000) return 'a and b each need 1 to 10^5 words.';
  const seen = new Set();
  let letters = 0;
  for (const list of [a, b]) {
    for (let i = 0; i < list.length; i++) {
      const word = list[i];
      if (typeof word !== 'string' || !/^[a-z]+$/.test(word)) return 'Each word is a non-empty string of lowercase letters.';
      if (i > 0 && list[i - 1] > word) return 'a and b must each be sorted lexicographically.';
      if (seen.has(word)) return 'No word may appear twice across a and b.';
      seen.add(word);
      letters += word.length;
    }
  }
  if (letters > 1000000) return 'The words may have at most 10^6 letters in total.';
  return null;
}

