function canAliceWin(a, b) {
  const lists = [a, b];
  const next = [1, 0];
  let last = a[0];
  let player = 1;

  while (true) {
    const words = lists[player];
    let p = next[player];
    while (p < words.length && words[p] < last) {
      p++;
    }
    if (p === words.length) {
      return player === 1;
    }
    const letter = words[p][0];
    const gap = letter.charCodeAt(0) - last.charCodeAt(0);
    if (gap > 1) {
      return player === 1;
    }
    while (p + 1 < words.length && words[p + 1][0] === letter) {
      p++;
    }
    last = words[p];
    next[player] = p + 1;
    player = 1 - player;
  }
}

