function canAliceWin(a, b) {
  // Full game search. Played words strictly increase, so the last word alone describes the position.
  const closelyGreater = (w, z) => {
    if (w.charCodeAt(0) !== z.charCodeAt(0) && w.charCodeAt(0) !== z.charCodeAt(0) + 1) return false;
    for (let i = 0; i < Math.min(w.length, z.length); i++) {
      if (w[i] !== z[i]) return w.charCodeAt(i) > z.charCodeAt(i);
    }
    return w.length > z.length;
  };
  const memo = new Map();
  // Can `mover` (0 = Alice, 1 = Bob) win when the word on the table is `last`?
  const wins = (last, mover) => {
    if (memo.has(last)) return memo.get(last);
    let result = false;
    for (const w of mover === 0 ? a : b) {
      if (closelyGreater(w, last) && !wins(w, 1 - mover)) {
        result = true;
        break;
      }
    }
    memo.set(last, result);
    return result;
  };
  return !wins(a[0], 1);
}

