function generate(rand, size) {
  const large = size === 'large';
  const span = large ? 20 + Math.floor(rand() * 7) : 2 + Math.floor(rand() * 3);
  const base = Math.floor(rand() * (27 - span));
  const sizeA = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 5);
  const sizeB = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 5);
  const maxLength = large ? 8 : 3;
  const letter = () => String.fromCharCode(97 + base + Math.floor(rand() * span));
  const seen = new Set();
  const a = [];
  const b = [];
  while (a.length < sizeA || b.length < sizeB) {
    const length = 1 + Math.floor(rand() * maxLength);
    let word = '';
    for (let i = 0; i < length; i++) word += letter();
    // Lengthen a repeated word until it is new, so every word is distinct.
    for (let i = 0; seen.has(word); i++) word += String.fromCharCode(97 + base + i % span);
    seen.add(word);
    const toA = b.length >= sizeB || (a.length < sizeA && rand() < sizeA / (sizeA + sizeB));
    (toA ? a : b).push(word);
  }
  a.sort();
  b.sort();
  return [a, b];
}
